type GetAssignmentsForPrincipalParams struct {
	PrincipalID   string
	PrincipalType string
}

const getAssignmentsForPrincipalSQL = `-- name: GetAssignmentsForPrincipal :many
SELECT ce.id, ce.external_id, ce.name, ce.url, ce.type, ce.status, ce.size, ce.max_memory_gb, ce.auth_token, ce.owner, ce.created_at, ce.updated_at, ce.selection_policy, ce.workload_class, ce.readiness_status, ce.max_concurrency, ce.max_result_size_mb, ce.recommended_for_large_queries, ce.is_draining, ce.last_health_status, ce.last_health_checked_at, ce.active_queries, ce.queued_jobs, ce.running_jobs, ce.completed_jobs, ce.stored_jobs, ce.cleaned_jobs, ce.query_result_ttl_seconds
FROM compute_endpoints ce
JOIN compute_assignments ca ON ca.endpoint_id = ce.id
WHERE ca.principal_id = ?
  AND ca.principal_type = ?
ORDER BY ca.is_default DESC, ce.name`

func (s *Store) GetAssignmentsForPrincipal(ctx context.Context, arg GetAssignmentsForPrincipalParams) ([]ComputeEndpoint, error) {
	rows, err := s.db.QueryContext(ctx, getAssignmentsForPrincipalSQL, arg.PrincipalID, arg.PrincipalType)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ComputeEndpoint
	for rows.Next() {
		var item ComputeEndpoint
		if err := rows.Scan(
			&item.ID,
			&item.ExternalID,
			&item.Name,
			&item.Url,
			&item.Type,
			&item.Status,
			&item.Size,
			&item.MaxMemoryGb,
			&item.AuthToken,
			&item.Owner,
			&item.CreatedAt,
			&item.UpdatedAt,
			&item.SelectionPolicy,
			&item.WorkloadClass,
			&item.ReadinessStatus,
			&item.MaxConcurrency,
			&item.MaxResultSizeMb,
			&item.RecommendedForLargeQueries,
			&item.IsDraining,
			&item.LastHealthStatus,
			&item.LastHealthCheckedAt,
			&item.ActiveQueries,
			&item.QueuedJobs,
			&item.RunningJobs,
			&item.CompletedJobs,
			&item.StoredJobs,
			&item.CleanedJobs,
			&item.QueryResultTtlSeconds,
		); err != nil {
			return nil, err
		}
		items = append(items, item)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

